-- A priori HITL classification seeds for the marketing connectors (24 new
-- types and salesloft's move to its vendor-hosted MCP), written BEFORE the
-- first customer connects, from each vendor's public surface — no vendor
-- account, key or token was held.
--
-- Vendor-hosted tools are discovered live per connection and were, until now,
-- classified only by MCP annotations and verb heuristics at enumeration time;
-- the global rows here (tenant_id IS NULL) are what tenant-runtime consults
-- first (GET /api/internal/tool-classifications/:integrationType). Each
-- block was produced by connector-service's
-- `classify:tools --from-inventory src/catalog/vendor-mcp-inventory/<type>.json`
-- (the five Composio-managed types from `--from-registry`; the overlay is their
-- registry) and reviewed by hand. The categories are the union of the sensitivity
-- categories the oversight gate matches on and the effect tokens the runtime
-- reads (write / destructive / outbound); a read is ARRAY[]::TEXT[].
--
-- A meta-tool server (omnisend) is seeded per OPERATION: rows keyed
-- `execute:<operation>` alongside its search / tool_schema / tool_documentation
-- reads; the runtime resolves an `execute` call to its `tool_name` argument.
--
-- Twenty-five connector types share tool names (`search`, `list_sites`,
-- `create_tag`), which the post-458 identity permits and the 459 compat index
-- forbids. That index existed to let a pre-458 binary keep upserting through
-- the migrate window and a rollback; 458–460 are on release and the rollback
-- window to a pre-458 revision has closed, so the index is dropped here, as 459
-- said a later release would. The conflict target below is the 458 identity.

DROP INDEX IF EXISTS tool_classification_cache_tenant_compat_key;

-- klaviyo
ON CONFLICT (tool_name, COALESCE(integration_type, ''), COALESCE(tenant_id, '__global__')) DO UPDATE
  SET categories = EXCLUDED.categories,
      tool_description_hash = EXCLUDED.tool_description_hash,
      reviewed_by = EXCLUDED.reviewed_by,
      classified_at = NOW();

